c='p4';B='PYTHON 6A'
def R(code,inp='',fs=22,lab='Kết quả chạy'): return RES(OUT(RUN(code,inp),fs),lab)
def V(code,inp=''): return RUN(code,inp)
A='a = [2, 5, 8, 12, 16, 23, 38, 56, 72, 91, 95, 99, 104, 110, 120]'
BS='def tim(a, k):\n    l, r = 0, len(a) - 1\n    dem = 0\n    while l <= r:\n        m = (l + r) // 2\n        dem += 1\n        if a[m] == k:\n            return m, dem\n        elif a[m] < k:\n            l = m + 1\n        else:\n            r = m - 1\n    return -1, dem'
S=[]
S.append(TITLE('TIN HỌC · PYTHON 6A','THUẬT TOÁN<br>TÌM KIẾM','Tìm kiếm tuần tự, tìm kiếm nhị phân, đếm số lần so sánh, vị trí đầu – cuối, tìm theo đáp án, ứng dụng bisect.',['tuần tự','nhị phân','log n','bisect','đáp án']))
S.append(goals(c,B,['Cài đặt <b>tìm kiếm tuần tự</b> và đánh giá O(n).','Cài đặt <b>tìm kiếm nhị phân</b> đúng, tránh <b>lặp vô hạn</b> và <b>lệch một</b>.','<b>Đếm số lần so sánh</b> của nhị phân theo từng bước.','Tìm <b>vị trí đầu tiên / cuối cùng</b> khi có giá trị trùng.','Hiểu <b>nhị phân trên đáp án</b>; dùng <code>bisect</code>.'],['Tìm tuần tự','Tìm nhị phân','Biến thể','Nhị phân trên đáp án','Tự kiểm tra, HSG']))
S.append(S2(c,B+' · 1','Bài toán tìm kiếm',card('Phát biểu',P('Cho dãy <b>a</b> có n phần tử và giá trị <b>k</b>. Tìm <b>vị trí</b> của k trong a, hoặc báo <b>không có</b> (thường trả <b>−1</b>).','Hai phương pháp chính: <b>tuần tự</b> (dãy bất kì) và <b>nhị phân</b> (dãy <b>đã sắp xếp</b>).')),CODE('a = [7, 3, 9, 3, 5, 8]\nprint(a.index(9))\nprint(3 in a, a.count(3))\nprint(a.index(3))\nprint(a.index(4))',22)+R('a = [7, 3, 9, 3, 5, 8]\nprint(a.index(9))\nprint(3 in a, a.count(3))\nprint(a.index(3))','',24,'Kết quả')+RES(OUT(ERR('a = [7, 3, 9]\nprint(a.index(4))'),20),'index báo lỗi nếu không có')))
S.append(S2(c,B+' · 1','Tìm kiếm tuần tự',card('Ý tưởng',STEPS(['Xét lần lượt <b>từng phần tử từ đầu</b>.','Gặp phần tử <b>bằng k</b>: trả vị trí, <b>dừng</b>.','Hết dãy mà chưra gặp: trả <b>−1</b>.'])+KEY('Tốt nhất 1 lần, xấu nhất <b>n</b> lần: <b>O(n)</b>. Không yêu cầu dãy sắp xếp.')),CODE('def tim_tt(a, k):\n    dem = 0\n    for i in range(len(a)):\n        dem += 1\n        if a[i] == k:\n            return i, dem\n    return -1, dem\n\na = [7, 3, 9, 3, 5, 8]\nprint(tim_tt(a, 7), tim_tt(a, 3))\nprint(tim_tt(a, 8), tim_tt(a, 4))'.replace('chưra','chưa'),20)+R('def tim_tt(a, k):\n    dem = 0\n    for i in range(len(a)):\n        dem += 1\n        if a[i] == k:\n            return i, dem\n    return -1, dem\na = [7, 3, 9, 3, 5, 8]\nprint(tim_tt(a, 7), tim_tt(a, 3))\nprint(tim_tt(a, 8), tim_tt(a, 4))','',22,'(vị trí, số lần so sánh)')+KEY('Phần tử 3 xuất hiện hai lần: tìm tuần tự trả vị trí <b>đầu tiên</b> (1).')))
S.append(S2(c,B+' · 2','Ý tưởng tìm nhị phân',card('Như đoán số trong trò chơi',P('Dãy <b>đã sắp xếp tăng</b>. So k với <b>phần tử giữa</b>:','• bằng → <b>tìm thấy</b>;','• k nhỏ hơn → chỉ còn <b>nửa trái</b>;','• k lớn hơn → chỉ còn <b>nửa phải</b>.','Mỗi lần so sánh <b>loại một nửa</b> → chỉ cần <b>≈ log₂ n</b> lần.')),RES('<svg viewBox="0 0 560 220" style="width:100%"><g font-family="sans-serif" font-weight="800" font-size="22" text-anchor="middle"><rect x="10" y="20" width="540" height="52" rx="8" fill="#BBDEFB" stroke="#1565C0" stroke-width="3"/><text x="280" y="55" fill="#0B2545">cả dãy: n phần tử</text><rect x="10" y="90" width="270" height="52" rx="8" fill="#C8E6C9" stroke="#2E7D32" stroke-width="3"/><text x="145" y="125" fill="#0B2545">còn n / 2</text><rect x="10" y="160" width="135" height="52" rx="8" fill="#FFF9C4" stroke="#F9A825" stroke-width="3"/><text x="78" y="195" fill="#0B2545">n / 4</text><text x="400" y="125" fill="#D84315">⌊log₂ n⌋ + 1 lần</text><text x="400" y="195" fill="#D84315">n = 10⁶ → 20</text></g></svg>','Mỗi bước giảm một nửa')))
S.append(S2(c,B+' · 2','Cài đặt tìm kiếm nhị phân',card('Ba biến l, r, m',P('<b>l, r</b>: hai đầu miền còn có thể chứa k. <b>m = (l + r) // 2</b>.','<b>a[m] &lt; k</b> → <b>l = m + 1</b>; <b>a[m] &gt; k</b> → <b>r = m − 1</b>.','Điều kiện lặp: <b>l ≤ r</b> (miền còn phần tử).')+KEY('<b>±1</b> là bắt buộc: m đã xét, bỏ đi. Thiếu thì <b>lặp vô hạn</b>.')),CODE(BS,19)+R(BS+'\na = [3, 8, 12, 17, 25, 31, 40]\nprint(tim(a, 31), tim(a, 3), tim(a, 4))','',24,'Kết quả (m, số lần so sánh)')))
S.append(TB(c,B+' · 2','Theo dõi tìm k = 31 trong [3, 8, 12, 17, 25, 31, 40]',['Lần','l','r','m','a[m]','so với 31','hành động'],[['1','0','6','3','17','17 &lt; 31','l = 4'],['2','4','6','5','31','<b>bằng</b>','trả m = 5']],note=KEY('Chỉ <b>2 lần</b> so sánh. Mảng 1000 phần tử: tối đa <b>⌊log₂ 1000⌋ + 1 = 10</b> lần.')))
S.append(S2(c,B+' · 2','Đếm số lần so sánh trên mảng 15 phần tử',card('Dãy a (15 phần tử)',P('<b>a</b> = 2, 5, 8, 12, 16, 23, 38, 56, 72, 91, 95, 99, 104, 110, 120.','Mọi phần tử tìm được sau <b>tối đa 4</b> lần so sánh (2⁴ − 1 = 15).','Hàm <b>tim</b> như slide trước (trả vị trí và số lần so sánh).')),CODE('for k in (95, 23, 56, 100):\n    print(k, tim(a, k)[1])',22)+R(BS+'\n'+A+'\nprint([tim(a, k)[1] for k in (95, 23, 56, 100)])','',24,'Số lần so sánh cho 95, 23, 56, 100')+KEY('56 nằm <b>chính giữa</b> (chỉ số 7): <b>1 lần</b>. 100 không có: duyệt hết nhánh, <b>4 lần</b> rồi trả −1.')))
S.append(S2(c,B+' · 2','Điều kiện: dãy phải được sắp xếp',card('Nhị phân trên dãy chưa sắp xếp sai!',P('Loại một nửa dựa trên giả thiết <b>nửa kia chắc chắn không chứa k</b> — đúng chỉ khi dãy tăng.','Dãy <b>giảm</b> thì đổi chiều so sánh. Dãy bất kì phải <b>sắp xếp trước</b> (O(n log n)).')),CODE('# hàm tim như slide trước\nb = [5, 1, 9, 3, 7]\nprint(tim(b, 7), tim(sorted(b), 7))',22)+R(BS+'\nb = [5, 1, 9, 3, 7]\nprint(tim(b, 7), tim(sorted(b), 7))','',24,'Dãy chưa sắp xếp: không tìm thấy 7 dù có')+KEY('Nên tìm <b>một lần</b> thì tuần tự rẻ hơn; tìm <b>nhiều lần</b> thì sắp xếp một lần rồi nhị phân.')))
S.append(S2(c,B+' · 3','Vị trí đầu tiên khi có giá trị trùng',card('Không dừng khi gặp',P('Khi a[m] == k, ta chưa chắc m là <b>đầu tiên</b>. Ghi nhận <b>kq = m</b> rồi <b>tiếp tục tìm bên trái</b> (<code>r = m − 1</code>).','Tìm <b>cuối cùng</b>: ghi nhận rồi tìm bên phải (<code>l = m + 1</code>).','Đếm số lần xuất hiện = cuối − đầu + 1.')),CODE('def dau(a, k):\n    l, r, kq = 0, len(a) - 1, -1\n    while l <= r:\n        m = (l + r) // 2\n        if a[m] == k:\n            kq = m\n            r = m - 1\n        elif a[m] < k:\n            l = m + 1\n        else:\n            r = m - 1\n    return kq\na = [1, 2, 2, 2, 3, 5]\nprint(dau(a, 2), dau(a, 4))',17)+R('def dau(a, k):\n    l, r, kq = 0, len(a) - 1, -1\n    while l <= r:\n        m = (l + r) // 2\n        if a[m] == k:\n            kq = m\n            r = m - 1\n        elif a[m] < k:\n            l = m + 1\n        else:\n            r = m - 1\n    return kq\na = [1, 2, 2, 2, 3, 5]\nprint(dau(a, 2), dau(a, 4))','',24,'Kết quả')))
S.append(S2(c,B+' · 3','Thư viện bisect',card('Có sẵn trong Python',P('<b>bisect_left(a, k)</b>: vị trí <b>đầu tiên</b> có thể chèn k (= vị trí đầu của k nếu có).','<b>bisect_right(a, k)</b>: vị trí <b>sau phần tử k cuối</b>.','Số lần k xuất hiện: <code>bisect_right − bisect_left</code>. Số phần tử &lt; k: <code>bisect_left</code>.')),CODE('from bisect import bisect_left, bisect_right\na = [1, 2, 2, 2, 3, 5]\nprint(bisect_left(a, 2), bisect_right(a, 2))\nprint(bisect_right(a, 2) - bisect_left(a, 2))\nprint(bisect_left(a, 4), bisect_left(a, 0))\nprint(bisect_right(a, 5) - bisect_left(a, 2))',20)+R('from bisect import bisect_left, bisect_right\na = [1, 2, 2, 2, 3, 5]\nprint(bisect_left(a, 2), bisect_right(a, 2))\nprint(bisect_right(a, 2) - bisect_left(a, 2))\nprint(bisect_left(a, 4), bisect_left(a, 0))\nprint(bisect_right(a, 5) - bisect_left(a, 2))','',22,'Kết quả')+KEY('Dòng cuối: số phần tử trong đoạn [2, 5] = 5.')))
S.append(S2(c,B+' · 3','Tìm phần tử gần nhất và các biến thể',card('Ứng dụng của bisect',P('Phần tử <b>nhỏ nhất ≥ k</b> (lower bound): <code>a[bisect_left(a, k)]</code> nếu chỉ số hợp lệ.','Phần tử <b>lớn nhất ≤ k</b>: <code>a[bisect_right(a, k) − 1]</code> nếu ≥ 0.','Nhờ vậy xử lí <b>hàng nghìn truy vấn</b> trong O(log n) mỗi truy vấn.')),CODE('from bisect import bisect_left, bisect_right\na = [3, 8, 12, 17, 25, 31, 40]\ndef gan_nhat(a, k):\n    i = bisect_left(a, k)\n    ung = []\n    if i < len(a): ung.append(a[i])\n    if i > 0: ung.append(a[i - 1])\n    return min(ung, key=lambda v: abs(v - k))\nprint(gan_nhat(a, 20), gan_nhat(a, 100), gan_nhat(a, 1))',19)+R('from bisect import bisect_left, bisect_right\na = [3, 8, 12, 17, 25, 31, 40]\ndef gan_nhat(a, k):\n    i = bisect_left(a, k)\n    ung = []\n    if i < len(a): ung.append(a[i])\n    if i > 0: ung.append(a[i - 1])\n    return min(ung, key=lambda v: abs(v - k))\nprint(gan_nhat(a, 20), gan_nhat(a, 100), gan_nhat(a, 1))','',24,'Kết quả')))
S.append(S2(c,B+' · 4','Nhị phân trên đáp án',card('Ý tưởng “mở rộng”',P('Không tìm trong mảng mà tìm trong <b>miền đáp án</b> khi bài toán có tính <b>đơn điệu</b>: nếu x thoả thì mọi x lớn hơn cũng thoả (hoặc ngược lại).','Hàm <b>kiểm tra(x)</b> trả đúng/sai; nhị phân tìm <b>x nhỏ nhất thoả</b>.','Ví dụ: tìm <b>căn bậc hai nguyên</b>; chia dây cho k người; số ngày xong việc…')),CODE('def isqrt(n):\n    l, r = 0, n\n    while l < r:\n        m = (l + r + 1) // 2\n        if m * m <= n:\n            l = m\n        else:\n            r = m - 1\n    return l\nprint(isqrt(99), isqrt(100), isqrt(10**18))',21)+R('def isqrt(n):\n    l, r = 0, n\n    while l < r:\n        m = (l + r + 1) // 2\n        if m * m <= n:\n            l = m\n        else:\n            r = m - 1\n    return l\nprint(isqrt(99), isqrt(100), isqrt(10**18))','',24,'Kết quả')+KEY('Dạng <b>l = m</b> cần <b>m = (l + r + 1) // 2</b> (lệch lên) để tránh lặp vô hạn.')))
S.append(S2(c,B+' · 4','Bài toán: cắt dây',card('Đề bài',P('Có n sợi dây dài a[i]. Cần cắt ra <b>ít nhất k đoạn bằng nhau</b> (mỗi đoạn dài nguyên L). Tìm <b>L lớn nhất</b>.','Kiểm tra(L): tổng <code>a[i] // L</code> ≥ k? L <b>càng nhỏ càng dễ thoả</b> → đơn điệu.','Nhị phân L từ 1 đến max(a): <b>O(n log max)</b>.')),CODE('def cat(a, k):\n    l, r = 0, max(a)\n    while l < r:\n        m = (l + r + 1) // 2\n        if sum(x // m for x in a) >= k:\n            l = m\n        else:\n            r = m - 1\n    return l\nprint(cat([802, 743, 457, 539], 11))\nprint(cat([5, 5], 20))',22)+R('def cat(a, k):\n    l, r = 0, max(a)\n    while l < r:\n        m = (l + r + 1) // 2\n        if sum(x // m for x in a) >= k:\n            l = m\n        else:\n            r = m - 1\n    return l\nprint(cat([802, 743, 457, 539], 11))\nprint(cat([5, 5], 20))','',24,'Kết quả')+KEY('Dây dài 802, 743, 457, 539 cắt đoạn 200: 4 + 3 + 2 + 2 = 11 đoạn → L = 200.')))
S.append(S2(c,B+' · 4','Các lỗi phổ biến của nhị phân',card('Bốn lỗi kinh điển',ul(['<b>l = m</b> hoặc <b>r = m</b> (thiếu ±1) → lặp vô hạn.','Điều kiện lặp <b>l &lt; r</b> thay vì <b>l ≤ r</b> → bỏ sót.','Dãy chưa sắp xếp.','Với chặn dưới/trên: sai lệch khi tìm <b>đầu tiên/cuối cùng</b>.'],7)+WARN('Khi thi, tự thử với dãy <b>1 phần tử</b>, <b>2 phần tử</b>, k nhỏ nhất, k lớn nhất, k không có.')),CODE('def tim_sai(a, k):\n    l, r = 0, len(a) - 1\n    while l <= r:\n        m = (l + r) // 2\n        if a[m] == k:\n            return m\n        elif a[m] < k:\n            l = m + 1\n        else:\n            r = m\n    return -1\nprint(tim_sai([1, 3, 5], 5))\nprint(tim_sai([1, 3, 5], 0))',19)+RES('<div style="font-size:22px">Với k = 0 (nhỏ hơn mọi phần tử): chương trình <b>lặp vô hạn</b> vì r = m không thu hẹp khi l = r = 0.</div>','Không chạy thử vì treo')))
S.append(SELF(c,B+' · 5','Tự kiểm tra: số lần so sánh','Mảng tăng 15 phần tử như trên. Tìm 95, 23, 56, 100 cần bao nhiêu lần so sánh?',A+'\n# dùng hàm tim ở trên\nprint([tim(a, k)[1] for k in (95, 23, 56, 100)])',P('Dãy có 15 phần tử, m đầu = 7 (giá trị 56).','<b>56</b>: bằng ngay → <b>1 lần</b>.','<b>23</b>: 23 &lt; 56 → trái [0..6], m = 3 (12) &lt; 23 → [4..6], m = 5 = 23: <b>3 lần</b>.','<b>95</b>: phải [8..14], m = 11 (99) &gt; 95 → [8..10], m = 9 (91) &lt; 95 → [10..10], m = 10: <b>4 lần</b>.','<b>100</b>: không có, tới khi l &gt; r: <b>4 lần</b>. Đáp án <b>4 3 1 4</b>.')+R(BS+'\n'+A+'\nprint([tim(a, k)[1] for k in (95, 23, 56, 100)])','',24,'Kết quả thật'),20))
S.append(SELF(c,B+' · 5','Tự kiểm tra (HSG): phát biểu đúng sai','Với a = [3, 8, 12, 17, 25, 31, 40], k = 31: (a) vị trí tìm thấy? (b) số lần so sánh? (c) vẫn đúng nếu dãy chưa sắp xếp? (d) mảng 1000 phần tử cần tối đa bao nhiêu lần?','a = [3, 8, 12, 17, 25, 31, 40]\nprint(tim(a, 31))',P('(a) chỉ số <b>5</b>. (b) <b>2 lần</b> (m = 3 rồi m = 5). (c) <b>Sai</b>: nhị phân chỉ đúng với dãy đã sắp xếp. (d) ⌊log₂ 1000⌋ + 1 = <b>10</b>.')+R(BS+'\na = [3, 8, 12, 17, 25, 31, 40]\nprint(tim(a, 31))\nimport math\nprint(math.floor(math.log2(1000)) + 1)','',24,'Kết quả thật'),20))
S+=END(c,B,['<b>Tuần tự</b>: duyệt từng phần tử, O(n), không cần sắp xếp.','<b>Nhị phân</b>: dãy đã sắp xếp, loại một nửa mỗi lần, O(log n).','Cập nhật <b>l = m + 1</b>, <b>r = m − 1</b>; điều kiện <b>l ≤ r</b>.','Số lần so sánh tối đa: <b>⌊log₂ n⌋ + 1</b>.','Vị trí đầu/cuối: ghi nhận kết quả rồi tìm tiếp một phía; <b>bisect_left/right</b>.','<b>Nhị phân trên đáp án</b> khi điều kiện đơn điệu.'],[('Tìm tuần tự','O(n)'),('Tìm nhị phân','O(log n)'),('Vị trí đầu','bisect_left'),('Điều kiện','dãy đã sắp xếp')],'Thiếu ±1; quên sắp xếp trước; nhầm đầu/cuối khi có trùng.',['Tìm 1 lần: tuần tự rẻ hơn sắp xếp + nhị phân.','<code>l = m</code> cần <code>m = (l + r + 1) // 2</code>.','<code>a.index</code> báo lỗi nếu không có.','Nhị phân trên đáp án: xác định <b>đơn điệu</b> trước.'],['<b>Tìm kiếm tam phân</b> cho hàm lồi.','<b>Nhị phân trên số thực</b>.','<b>Fractional cascading</b>.'],
 [('Mảng 1 000 000 phần tử: nhị phân tối đa mấy lần so sánh?',),('Dãy phải thoả điều kiện gì?',),('<code>bisect_left([1,2,2,3], 2)</code>?',),('<code>bisect_right([1,2,2,3], 2)</code>?',),('Tìm tuần tự trả vị trí đầu hay cuối khi có trùng?',)],
 [('<b>20</b>.',),('<b>Đã sắp xếp</b>.',),('<b>1</b>.',),('<b>3</b>.',),('<b>Đầu tiên</b>.',)],
 [('Mức 1. Viết tìm kiếm tuần tự trả vị trí <b>cuối cùng</b> của k. Thử [7,3,9,3,5,8], k = 3.',),('Mức 1. Dùng nhị phân kiểm tra k có trong dãy tăng. Thử [2,5,8,12], k = 8 và 9.',),('Mức 2. Đếm số lần k xuất hiện trong dãy tăng bằng bisect. Thử [1,2,2,2,3,5], k = 2.',),('Mức 2. Tìm phần tử <b>nhỏ nhất ≥ k</b>. Thử [3,8,12,17], k = 10.',),('Mức 3 (HSG). Cắt dây: n dây, cần ≥ k đoạn bằng nhau, tìm L lớn nhất. Thử [802,743,457,539], k = 11.',),('Mức 3 (HSG). Cho dãy tăng và q truy vấn (l, r): đếm số phần tử trong [l, r] bằng bisect. n = 10⁵, q = 10⁵.',)],
 [(V('a=[7,3,9,3,5,8]\nprint(max(i for i,x in enumerate(a) if x==3))')+'.',),(V('from bisect import bisect_left\na=[2,5,8,12]\nfor k in (8,9):\n    i=bisect_left(a,k)\n    print(i<len(a) and a[i]==k, end=" ")')+'.',),(V('from bisect import *\nprint(bisect_right([1,2,2,2,3,5],2)-bisect_left([1,2,2,2,3,5],2))')+'.',),(V('from bisect import *\na=[3,8,12,17]\nprint(a[bisect_left(a,10)])')+'.',),('Đáp án 200 (xem slide “Cắt dây”).',),('<code>bisect_right(a, r) − bisect_left(a, l)</code>: O(log n) mỗi truy vấn; tổng O(q log n).',)],hper=2)
